  assertDocument("{\"name\":}", BEGIN_OBJECT, NAME, MalformedJsonException.class);
  assertDocument("{\"name\"::", BEGIN_OBJECT, NAME, MalformedJsonException.class);
  assertDocument("{\"name\":,", BEGIN_OBJECT, NAME, MalformedJsonException.class);
